var GRIDINFO_RU = {
  law:{head:'Право — ДА, если выбрать узкую специализацию. Самый обычный путь в него — НЕТ.', short:'«Право» — это не одна работа, а несколько очень разных. Нужны и будут нужны: защита данных и правила для ИИ, проверка компаний перед сделками, правила в медицине. Там вакансии платят до $319K. Помощник юриста на все руки (generalist paralegal) — плохой выбор. Юрфак без ясной цели — тоже.'},
  cpa:{head:'Бухгалтерия — ДА, если выбрать узкую специализацию. Самые обычные работы — НЕТ.', short:'«Бухгалтер» — это не одна работа, а девять разных. Бухгалтер «на все руки» — плохой выбор: эту работу первой заберут программы и ИИ. Просто записывать операции — тоже тупик, если это цель. А узкие специалисты нужны и будут нужны. Это сложные налоги, отчётность для биржи, проверка компаний перед покупкой, финансовые расследования и контролёры. Им платят $120K–$225K. Итог: профессия жива, но только в узкой нише.'},
  nurse:{head:'Сестринское дело — это ДА. Самый обычный путь в него — НЕТ.', short:'Всё зависит от того, какой медсестрой вы станете. Будут нужны: медсестра узкой специальности (specialty RN), психиатрическая медсестра-практик (psych NP), медсестра-анестезист (CRNA) и контрактная медсестра (travel). Общая палата (med-surg) как конечная остановка — тупик. Старт с младшей медсестры (LPN) — плохой выбор. Семейная практика без специальности (generalist FNP) в больших городах — тоже: таких уже слишком много.'},
  fin:{head:'«Финансовый аналитик» — это пять разных работ. Три растут. Одна — ловушка. В одну очень трудно попасть.', short:'«Финансовый аналитик» (financial analyst) — это пять разных работ. Общая отчётность (generalist reporting) — ловушка: обычно платят $103,570, а вакансий для новичков стало меньше на 21%. Партнёру по планированию (FP&A partnering) платят до $276,250. Хорошо платят и стратегические финансы (strategic finance), и гибрид с аналитикой (analytics hybrid).'},
  creator:{head:'Штатный контент-креатор — это YES. Тексты для медиа — это NO.', short:'Эта проверка — про креатора в штате компании, на зарплате. Не про независимого блогера. «Креатор» на работе — это пять разных работ. Бренд, где вы — вся студия, — YES. Лицо бренда — YES. Платная реклама — YES. Агентство — школа, а не конечная. Медиа и тексты — NO: самая низкая оплата из 40 вакансий в нашем разборе. И первое место, где черновик пишет ИИ.'},
  analyst:{head:'Аналитик — это ДА. Работа только с отчётами — это НЕТ.', short:'«Аналитик» — это шесть работ. Две отчётные — плохой конец: писать требования и делать отчёты с графиками по запросу. Хороши работы, где принимают решения: аналитик продукта (product analyst) и стратегия и операции (strategy & operations). Хорош и инженер данных (analytics engineer), который строит таблицы. Платят $96K–$300K.'},
  dataanalyst:{head:'«Аналитик данных» (data analyst) — это четыре работы. Одна — ловушка. В двух платят за решения. Одна строит модели.', short:'«Аналитик данных» (data analyst) — это четыре разные работы. Отчёты с графиками по запросу — тупик: $60K–$75K на старте и 1,108 заявок на одно место для новичка. Хороший выбор — аналитик продукта (product analyst), который помогает решать. И инженер данных (analytics engineer), который строит чистые таблицы. Платят $96K–$300K.'},
  businessanalyst:{head:'Бизнес-аналитик — это две работы. Та, что пишет документы, — НЕТ. Та, что помогает руководителям принимать решения, — ДА.', short:'Бизнес-аналитик — это две разные работы. Писать документы с требованиями — тупик: начинающим платят $51K–$82K, а главный продукт теперь пишет ИИ. Помогать руководителям решать (strategy & operations) — хороший путь: Google даёт $124K–$177K. Одно название, разная работа.'}
};

